customCss:
/* ==========================================================================

RESET EXCLUSIVO DE MÁRGENES EXTERNOS (Inter-elementos a 0px)
========================================================================== */

/* Ponemos a 0px estrictamente los márgenes superior e inferior de todos los bloques,
pero únicamente dentro del editor o de la vista de código Markdown. Esto evita
que se alteren las pestañas u otros menús nativos del editor MarkText.
*/
.mu-editor-area div[data-block-id],
.mu-paragraph,
.mu-editor-area p,
.markdown-body p,
.mu-editor-area ul,
.mu-editor-area ol,
.markdown-body ul,
.markdown-body ol,
.mu-blockquote,
.markdown-body blockquote,
.mu-code-block,
.mu-fenced-code,
.mu-editor-area pre,
.markdown-body pre,
.markdown-body .highlight,
.mu-heading,
.mu-editor-area h1,
.mu-editor-area h2,
.mu-editor-area h3,
.mu-editor-area h4,
.mu-editor-area h5,
.mu-editor-area h6,
.markdown-body h1,
.markdown-body h2,
.markdown-body h3,
.mu-editor-area table,
.markdown-body table {
margin-top: 0px !important;
margin-bottom: 0px !important;
}

/* Forzamos el color gris de tu texto de Glow para párrafos y listas sin alterar su flujo */
.mu-paragraph,
.mu-editor-area p,
.markdown-body p {
line-height: 1.5 !important;
color: #9c9898 !important;
}

/* Conservamos la sangría izquierda para que las listas sigan siendo legibles jerárquicamente */
.mu-editor-area ul,
.mu-editor-area ol,
.markdown-body ul,
.markdown-body ol {
padding-left: 2em !important;
}

/* ==========================================================================
1.2 COMPACTACIÓN ESTRICTA DE LISTAS (Sin espacios entre elementos)
========================================================================== */

/* Forzamos que cada viñeta o número individual esté pegado verticalmente al anterior,
delimitándolo exclusivamente al documento para proteger los menús del editor.
*/
.mu-editor-area li,
.markdown-body li {
margin-top: 0px !important;
margin-bottom: 0px !important;
padding-top: 0px !important;
padding-bottom: 0px !important;
line-height: 1.5 !important;
color: #9c9898 !important;
}

/* Si el editor mete párrafos invisibles dentro de las listas, los compactamos también */
.mu-editor-area li p,
.markdown-body li p {
margin-top: 0px !important;
margin-bottom: 0px !important;
padding-top: 0px !important;
padding-bottom: 0px !important;
}

/* ==========================================================================
2. Estilos Cosméticos de Títulos (Colores de tu Glow con márgenes a cero)
========================================================================== */

/* H1: Amarillo crema con fondo morado/azul (Glow ANSI 228 sobre 63) /
.mu-editor-area h1,
.markdown-body h1 {
color: #ffff87 !important;

background-color: #5f00ff !important;
padding-left: 8px !important;
padding-right: 8px !important;
padding-top: 2px !important;
padding-bottom: 2px !important;
border-radius: 4px !important;
border-bottom: none !important;
display: inline-block !important; / El fondo solo cubre el texto */
}

/* H2: Alineado a la izquierda, color Cian (#45f3de), fondo oscuro (#262626)
y línea inferior continua de lado a lado /
.mu-editor-area h2,
.markdown-body h2 {
display: block !important;
text-align: left !important;
color: #45f3de !important;

background-color: #262626 !important;
border-bottom: 2px solid #45f3de !important;
padding-top: 6px !important;
padding-left: 10px !important;
padding-right: 10px !important;
padding-bottom: 8px !important; / Mantiene la separación visual interna sobre el borde */
border-radius: 4px 4px 0 0 !important;
font-size: 1.4em !important;
}

/* H3: Color Azul Cielo (Glow #2ac3de) con fondo oscuro (ANSI 235) */
.mu-editor-area h3,
.markdown-body h3 {
display: inline-block !important;
color: #2ac3de !important;

background-color: #262626 !important;
padding-left: 8px !important;
padding-right: 8px !important;
padding-top: 2px !important;
padding-bottom: 2px !important;
border-radius: 4px !important;
}

/* ==========================================================================
3. TIPOGRAFÍA PRESTIGIO Y DISEÑO DE CÓDIGO (Monospace Pro)
========================================================================== */

/* Aplicamos una fuente de desarrollo premium para el código en línea /
.mu-editor-area code,
.mu-inline-code,
.markdown-body code {
color: #b570f7 !important;            / El morado característico de tu Glow /
background-color: #262626 !important; / El fondo oscuro ANSI 235 /
padding-left: 6px !important;
padding-right: 6px !important;
padding-top: 2px !important;
padding-bottom: 2px !important;
border-radius: 4px !important;
font-size: 0.9em !important;          / Ligeramente más pequeña para equilibrar la línea */

/* Font Stack de alta fidelidad para desarrollo en Linux */
font-family: "JetBrains Mono", "Fira Code", "Hack", "Liberation Mono", "Symbols Nerd Font Mono", monospace !important;


}

/* RESET y Tipografía para Bloques de Código grandes (```) para que hereden la fuente profesional */
.mu-code-block code,
.mu-fenced-code code,
.mu-code-sandbox code,
.mu-editor-area pre code,
.markdown-body pre code,
.markdown-body .highlight pre,
.CodeMirror-code span,
.CodeMirror-line span {
color: inherit !important;
background-color: transparent !important;
padding-left: 0 !important;
padding-right: 0 !important;
padding-top: 0 !important;
padding-bottom: 0 !important;
border-radius: 0 !important;

/* Forzamos la misma tipografía para los bloques grandes de código de MarkText */
font-family: "JetBrains Mono", "Fira Code", "Hack", "Liberation Mono", "Symbols Nerd Font Mono", monospace !important;


}

/* ==========================================================================
4. Formato Inline Secundario (Glow)
========================================================================== */

/* Negritas de tu Glow (#bcbcbc) */
.mu-editor-area strong,
.mu-inline-strong,
.markdown-body strong {
color: #bcbcbc !important;
font-weight: bold !important;
}

/* Enlaces de tu Glow (#7aa2f7) */
.mu-editor-area a,
.mu-inline-link,
.markdown-body a {
color: #7aa2f7 !important;
text-decoration: underline !important;
}

